changeSet.sql:

if not exists (select 1 from [sys].[key_constraints] where name = 'PK_MetricRollupPathSegment')
begin
	ALTER TABLE [metrics].[RollupPathSegment] ADD CONSTRAINT [PK_MetricRollupPathSegment] PRIMARY KEY CLUSTERED ( [RollupPathUid] ASC, [Position] ASC )
end

if not exists (select 1 from [INFORMATION_SCHEMA].[REFERENTIAL_CONSTRAINTS] where constraint_name = 'FK_MetricRollupPathSegment_AssetType')
begin
	ALTER TABLE [metrics].[RollupPathSegment]  WITH CHECK ADD  CONSTRAINT [FK_MetricRollupPathSegment_AssetType] FOREIGN KEY([AssetTypeID]) REFERENCES [dbo].[AssetType] ([ID]) ON DELETE SET NULL;
	ALTER TABLE [metrics].[RollupPathSegment] CHECK CONSTRAINT [FK_MetricRollupPathSegment_AssetType];
end

if not exists (select 1 from [INFORMATION_SCHEMA].[REFERENTIAL_CONSTRAINTS] where constraint_name = 'FK_MetricRollupPathSegment_MetricRollupPath')
begin
	ALTER TABLE [metrics].[RollupPathSegment]  WITH CHECK ADD  CONSTRAINT [FK_MetricRollupPathSegment_MetricRollupPath] FOREIGN KEY([RollupPathUid]) REFERENCES [metrics].[RollupPath] ([Uid]) ON DELETE CASCADE;
	ALTER TABLE [metrics].[RollupPathSegment] CHECK CONSTRAINT [FK_MetricRollupPathSegment_MetricRollupPath];
end
